"use strict";

var WORKLETIZED_ARGUMENTS = { useAnimatedStyle: [0] };

module.exports = function reanimatedPlugin(babel) {
  var t = babel.types;

  function collectClosure(functionPath) {
    var captured = new Set();
    functionPath.traverse({
      Identifier: function (identifierPath) {
        if (!identifierPath.isReferencedIdentifier()) return;
        var binding = identifierPath.scope.getBinding(identifierPath.node.name);
        if (binding && !functionPath.isAncestor(binding.path)) captured.add(binding.identifier.name);
      },
    });
    return Array.from(captured);
  }

  function workletize(functionPath) {
    var worklet = t.identifier("worklet");
    var closure = t.objectExpression(
      collectClosure(functionPath).map(function (name) {
        return t.objectProperty(t.identifier(name), t.identifier(name), false, true);
      }),
    );
    functionPath.replaceWith(
      t.callExpression(
        t.arrowFunctionExpression(
          [],
          t.blockStatement([
            t.variableDeclaration("const", [t.variableDeclarator(worklet, functionPath.node)]),
            t.expressionStatement(
              t.assignmentExpression("=", t.memberExpression(worklet, t.identifier("__closure")), closure),
            ),
            t.expressionStatement(
              t.assignmentExpression(
                "=",
                t.memberExpression(worklet, t.identifier("__workletHash")),
                t.numericLiteral(functionPath.getSource().length),
              ),
            ),
            t.returnStatement(worklet),
          ]),
        ),
        [],
      ),
    );
  }

  return {
    name: "fixture-reanimated-plugin",
    visitor: {
      CallExpression: function (callPath) {
        var callee = callPath.node.callee;
        if (!t.isIdentifier(callee)) return;
        var indices = WORKLETIZED_ARGUMENTS[callee.name];
        if (!indices) return;
        indices.forEach(function (index) {
          var argumentPath = callPath.get("arguments." + index);
          if (argumentPath.isArrowFunctionExpression() || argumentPath.isFunctionExpression()) {
            workletize(argumentPath);
          }
        });
      },
    },
  };
};
